<script setup lang="ts">import {ref,computed} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Empty from '../components/common/Empty.vue';import Status from '../components/common/Status.vue';import Table from '../components/common/Table.vue';import InferenceSummary from '../components/InferenceSummary.vue';import StateBands from '../components/StateBands.vue';import PosteriorGrid from '../components/PosteriorGrid.vue';import ProfileMatrix from '../components/ProfileMatrix.vue';import {fmt} from '../utils/format';const p=defineProps<{runs:any[];selectedId:number}>(),emit=defineEmits(['open']),traceId=ref(0),run=computed(()=>p.runs.find(r=>r.id===p.selectedId)||p.runs[0]),trace=computed(()=>run.value?.result?.traces.find(t=>t.id===traceId.value)||run.value?.result?.traces[0]);function open(e:Event){emit('open',p.runs.find(r=>r.id===Number((e.target as HTMLSelectElement).value)))}</script><template><PageTitle index="04" title="单点分布，与整段联合路径分开读。" description="前向后向得到边际后验；Viterbi得到固定模型下整段联合MAP。"/><label>结果运行<select :value="run?.id||0" @change="open"><option v-for="r in runs" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><p v-if="run"><Status :value="run.status"/>　{{run.error}}</p><template v-if="run?.result"><InferenceSummary :result="run.result"/><label>观测轨迹<select :value="trace?.id||0" @change="traceId=Number(($event.target as HTMLSelectElement).value)"><option v-for="t in run.result.traces" :key="t.id" :value="t.id">{{t.reference}}</option></select></label><div class="trace-metrics"><span>序列logL <strong>{{fmt(trace.log_likelihood,8)}}</strong></span><span>联合MAP logP <strong>{{fmt(trace.viterbi_log_joint,8)}}</strong></span><span>{{trace.linear_likelihood_underflows?'线性概率下溢，logL仍有限':'线性概率 '+trace.likelihood_if_representable.toExponential(6)}}</span></div><StateBands :trace="trace" :states="run.result.states"/><PosteriorGrid :trace="trace" :states="run.result.states"/><section class="section"><h2>所选轨迹逐条核对</h2><Table :headers="['轨迹','步数','序列logL','联合MAP logP','单点拼接合法性']"><tr v-for="t in run.result.traces" :key="t.id"><td>{{t.reference}}</td><td>{{t.tokens.length}}</td><td>{{fmt(t.log_likelihood,7)}}</td><td>{{fmt(t.viterbi_log_joint,7)}}</td><td>{{t.marginal_path_is_legal?'合法（仍非联合定义）':'非法零概率路径'}}</td></tr></Table></section><ProfileMatrix :profile="run.result.profile"/><details class="provenance"><summary>冻结指纹与所选轨迹完整log数组</summary><p class="fingerprint">{{run.result.fingerprint}}</p><p>{{trace.tie_rule}}</p><p>{{trace.null_log_meaning}}</p><Table :headers="['步','观测','log forward','log backward']"><tr v-for="(token,i) in trace.tokens" :key="i"><td>{{Number(i)+1}}</td><td>{{token}}</td><td>{{JSON.stringify(trace.log_forward[i])}}</td><td>{{JSON.stringify(trace.log_backward[i])}}</td></tr></Table></details><div class="boundary-note"><strong>隐态由固定模型定义，不是故障事实。</strong><p>同一观测在不同参数版本下可有不同解释；这里没有EM训练、在线告警或真实设备诊断保证。</p></div><a href="#notes" class="text-action">建立工况核对说明 →</a></template><Empty v-else :title="run?.status==='failed'?'本次观测在模型下不可行或推断失败':'等待真实worker推断'" :help="run?.error||'核对观测字母表与模型后，选择1–30条轨迹排队。'"/></template>
